INSERT INTO equipment VALUES (175,'Torch','Goods and Services','Item','Adventuring Gear','1 cp',NULL,NULL,NULL,NULL,'1 lb.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'A torch burns for 1 hour, clearly illuminating a 20-foot radius and providing shadowy illumination out to a 40- foot radius. If a torch is used in combat, treat it as a one-handed improvised weapon that deals bludgeoning damage equal to that of a gauntlet of its size, plus 1 point of fire damage.','SRD 3.5 Equipment');
INSERT INTO equipment VALUES (176,'Vial, ink or potion','Goods and Services','Item','Adventuring Gear','1 gp',NULL,NULL,NULL,NULL,'1/10 lb.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'A vial holds 1 ounce of liquid. The stoppered container usually is no more than 1 inch wide and 3 inches high.','SRD 3.5 Equipment');
INSERT INTO equipment VALUES (177,'Waterskin','Goods and Services','Item','Adventuring Gear','1 gp',NULL,NULL,NULL,NULL,'4 lb.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','SRD 3.5 Equipment');
INSERT INTO equipment VALUES (178,'Whetstone','Goods and Services','Item','Adventuring Gear','2 cp',NULL,NULL,NULL,NULL,'1 lb.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','SRD 3.5 Equipment');
INSERT INTO equipment VALUES (179,'Acid (flask)','Goods and Services','Item','Special Substances and Items','10 gp',NULL,NULL,NULL,NULL,'1 lb.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'You can throw a flask of acid as a splash weapon. Treat this attack as a ranged touch attack with a range increment of 10 feet. A direct hit deals 1d6 points of acid damage. Every creature within 5 feet of the point where the acid hits takes 1 point of acid damage from the splash.','SRD 3.5 Equipment');
INSERT INTO equipment VALUES (180,'Alchemist\'s fire (flask)','Goods and Services','Item','Special Substances and Items','20 gp',NULL,NULL,NULL,NULL,'1 lb.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'You can throw a flask of alchemist\'s fire as a splash weapon. Treat this attack as a ranged touch attack with a range increment of 10 feet. A direct hit deals 1d6 points of fire damage. Every creature within 5 feet of the point where the flask hits takes 1 point of fire damage from the splash. On the round following a direct hit, the target takes an additional 1d6 points of damage. If desired, the target can use a full-round action to attempt to extinguish the flames before taking this additional damage. Extinguishing the flames requires a DC 15 Reflex save. Rolling on the ground provides the target a +2 bonus on the save. Leaping into a lake or magically extinguishing the flames automatically smothers the fire.','SRD 3.5 Equipment');
INSERT INTO equipment VALUES (181,'Antitoxin (vial)','Goods and Services','Item','Special Substances and Items','50 gp',NULL,NULL,NULL,NULL,'-',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'If you drink antitoxin, you get a +5 alchemical bonus on Fortitude saving throws against poison for 1 hour.','SRD 3.5 Equipment');
INSERT INTO equipment VALUES (182,'Everburning torch','Goods and Services','Item','Special Substances and Items','110 gp',NULL,NULL,NULL,NULL,'1 lb.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'This otherwise normal torch has a continual flame spell cast upon it. An everburning torch clearly illuminates a 20-foot radius and provides shadowy illumination out to a 40-foot radius.','SRD 3.5 Equipment');
INSERT INTO equipment VALUES (183,'Holy water (flask)','Goods and Services','Item','Special Substances and Items','25 gp',NULL,NULL,NULL,NULL,'1 lb.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Holy water damages undead creatures and evil outsiders almost as if it were acid. A flask of holy water can be thrown as a splash weapon. Treat this attack as a ranged touch attack with a range increment of 10 feet. A flask breaks if thrown against the body of a corporeal creature, but to use it against an incorporeal creature, you must open the flask and pour the holy water out onto the target. Thus, you can douse an incorporeal creature with holy water only if you are adjacent to it. Doing so is a ranged touch attack that does not provoke attacks of opportunity. A direct hit by a flask of holy water deals 2d4 points of damage to an undead creature or an evil outsider. Each such creature within 5 feet of the point where the flask hits takes 1 point of damage from the splash. Temples to good deities sell holy water at cost (making no profit).','SRD 3.5 Equipment');
INSERT INTO equipment VALUES (184,'Smokestick','Goods and Services','Item','Special Substances and Items','20 gp',NULL,NULL,NULL,NULL,'1/2 lb.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'This alchemically treated wooden stick instantly creates thick, opaque smoke when ignited. The smoke fills a 10- foot cube (treat the effect as a fog cloud spell, except that a moderate or stronger wind dissipates the smoke in 1 round). The stick is consumed after 1 round, and the smoke dissipates naturally.','SRD 3.5 Equipment');
INSERT INTO equipment VALUES (185,'Sunrod','Goods and Services','Item','Special Substances and Items','2 gp',NULL,NULL,NULL,NULL,'1 lb.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'This 1-foot-long, gold-tipped, iron rod glows brightly when struck. It clearly illuminates a 30-foot radius and provides shadowy illumination in a 60-foot radius. It glows for 6 hours, after which the gold tip is burned out and worthless.','SRD 3.5 Equipment');
INSERT INTO equipment VALUES (186,'Tanglefoot bag','Goods and Services','Item','Special Substances and Items','50 gp',NULL,NULL,NULL,NULL,'4 lb.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'When you throw a tanglefoot bag at a creature (as a ranged touch attack with a range increment of 10 feet), the bag comes apart and the goo bursts out, entangling the target and then becoming tough and resilient upon exposure to air. An entangled creature takes a -2 penalty on attack rolls and a -4 penalty to Dexterity and must make a DC 15 Reflex save or be glued to the floor, unable to move. Even on a successful save, it can move only at half speed. Huge or larger creatures are unaffected by a tanglefoot bag. A flying creature is not stuck to the floor, but it must make a DC 15 Reflex save or be unable to fly (assuming it uses its wings to fly) and fall to the ground. A tanglefoot bag does not function underwater. A creature that is glued to the floor (or unable to fly) can break free by making a DC 17 Strength check or by dealing 15 points of damage to the goo with a slashing weapon. A creature trying to scrape goo off itself, or another creature assisting, does not need to make an attack roll; hitting the goo is automatic, after which the creature that hit makes a damage roll to see how much of the goo was scraped off. Once free, the creature can move (including flying) at half speed. A character capable of spellcasting who is bound by the goo must make a DC 15 Concentration check to cast a spell. The goo becomes brittle and fragile after 2d4 rounds, cracking apart and losing its effectiveness. An application of universal solvent to a stuck creature dissolves the alchemical goo immediately.','SRD 3.5 Equipment');
INSERT INTO equipment VALUES (187,'Thunderstone','Goods and Services','Item','Special Substances and Items','30 gp',NULL,NULL,NULL,NULL,'1 lb.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'You can throw this stone as a ranged attack with a range increment of 20 feet. When it strikes a hard surface (or is struck hard), it creates a deafening bang that is treated as a sonic attack. Each creature within a 10-foot-radius spread must make a DC 15 Fortitude save or be deafened for 1 hour. A deafened creature, in addition to the obvious effects, takes a -4 penalty on initiative and has a 20% chance to miscast and lose any spell with a verbal component that it tries to cast. Since you don\'t need to hit a specific target, you can simply aim at a particular 5-foot square. Treat the target square as AC 5.','SRD 3.5 Equipment');
INSERT INTO equipment VALUES (188,'Tindertwig','Goods and Services','Item','Special Substances and Items','1 gp',NULL,NULL,NULL,NULL,'-',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The alchemical substance on the end of this small, wooden stick ignites when struck against a rough surface. Creating a flame with a tindertwig is much faster than creating a flame with flint and steel (or a magnifying glass) and tinder. Lighting a torch with a tindertwig is a standard action (rather than a full-round action), and lighting any other fire with one is at least a standard action.','SRD 3.5 Equipment');
INSERT INTO equipment VALUES (189,'Alchemist\'s lab','Goods and Services','Item','Tools and Skill Kits','500 gp',NULL,NULL,NULL,NULL,'40 lb.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'An alchemist\'s lab always has the perfect tool for making alchemical items, so it provides a +2 circumstance bonus on Craft (alchemy) checks. It has no bearing on the costs related to the Craft (alchemy) skill. Without this lab, a character with the Craft (alchemy) skill is assumed to have enough tools to use the skill but not enough to get the +2 bonus that the lab provides.','SRD 3.5 Equipment');
INSERT INTO equipment VALUES (190,'Artisan\'s tools','Goods and Services','Item','Tools and Skill Kits','5 gp',NULL,NULL,NULL,NULL,'5 lb.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'These special tools include the items needed to pursue any craft. Without them, you have to use improvised tools (-2 penalty on Craft checks), if you can do the job at all.','SRD 3.5 Equipment');
INSERT INTO equipment VALUES (191,'Artisan\'s tools, masterwork','Goods and Services','Item','Tools and Skill Kits','55 gp',NULL,NULL,NULL,NULL,'5 lb.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'These tools serve the same purpose as artisan\'s tools (above), but masterwork artisan\'s tools are the perfect tools for the job, so you get a +2 circumstance bonus on Craft checks made with them.','SRD 3.5 Equipment');
INSERT INTO equipment VALUES (192,'Climber\'s kit','Goods and Services','Item','Tools and Skill Kits','80 gp',NULL,NULL,NULL,NULL,'5 lb.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'This is the perfect tool for climbing and gives you a +2 circumstance bonus on Climb checks.','SRD 3.5 Equipment');
INSERT INTO equipment VALUES (193,'Disguise kit','Goods and Services','Item','Tools and Skill Kits','50 gp',NULL,NULL,NULL,NULL,'8 lb.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The kit is the perfect tool for disguise and provides a +2 circumstance bonus on Disguise checks. A disguise kit is exhausted after ten uses.','SRD 3.5 Equipment');
INSERT INTO equipment VALUES (194,'Healer\'s kit','Goods and Services','Item','Tools and Skill Kits','50 gp',NULL,NULL,NULL,NULL,'1 lb.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'It is the perfect tool for healing and provides a +2 circumstance bonus on Heal checks. A healer\'s kit is exhausted after ten uses.','SRD 3.5 Equipment');
INSERT INTO equipment VALUES (195,'Holly and mistletoe','Goods and Services','Item','Tools and Skill Kits','-',NULL,NULL,NULL,NULL,'-',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','SRD 3.5 Equipment');
INSERT INTO equipment VALUES (196,'Holy symbol, wooden','Goods and Services','Item','Tools and Skill Kits','1 gp',NULL,NULL,NULL,NULL,'-',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'A holy symbol focuses positive energy. A cleric or paladin uses it as the focus for his spells and as a tool for turning undead. Each religion has its own holy symbol. Unholy Symbols: An unholy symbol is like a holy symbol except that it focuses negative energy and is used by evil clerics (or by neutral clerics who want to cast evil spells or command undead).','SRD 3.5 Equipment');
INSERT INTO equipment VALUES (197,'Holy symbol, silver','Goods and Services','Item','Tools and Skill Kits','25 gp',NULL,NULL,NULL,NULL,'1 lb.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'A holy symbol focuses positive energy. A cleric or paladin uses it as the focus for his spells and as a tool for turning undead. Each religion has its own holy symbol. Unholy Symbols: An unholy symbol is like a holy symbol except that it focuses negative energy and is used by evil clerics (or by neutral clerics who want to cast evil spells or command undead).','SRD 3.5 Equipment');
